begin;
do $$
declare
  v_site_id uuid;
  v_page_id uuid;
  v_document jsonb;
begin
  select id into v_site_id from website.sites where site_key='marktone-main' limit 1;
  select id into v_page_id from website.pages where site_id=v_site_id and is_home and status<>'archived' limit 1;
  if v_page_id is null then raise exception 'marktone_home_page_not_found'; end if;

  select content into v_document from website.pages where id=v_page_id for update;
  v_document:=jsonb_set(
    coalesce(v_document,'{}'::jsonb),
    '{blocks}',
    coalesce(v_document->'blocks','[]'::jsonb)||$blocks$[{"id":"row-stats","type":"columns","props":{"anchor":"","row":true,"layoutKey":"1","gap":0,"fullWidth":false,"minHeight":0,"verticalAlign":"stretch","items":[{"id":"col-stats","width":"1fr","modules":[{"id":"stats-value","type":"stats","props":{"anchor":"","eyebrow":"قيمة تشغيلية حقيقية","title":"بدل المزيد من الأدوات… احصل على رؤية واحدة","body":"من المصدر الأول للعميل حتى نتيجة التسجيل والتشغيل.","columns":4,"items":[{"value":"360°","title":"رؤية موحدة","description":"العميل، الفريق، الحملات والتشغيل في سياق واحد."},{"value":"لحظي","title":"مؤشرات قابلة للتصرف","description":"اعرف أين تتدخل وما الذي يحتاج متابعة الآن."},{"value":"موحّد","title":"مصدر واحد للحقيقة","description":"توقف عن مطابقة ملفات وتقارير متعارضة."},{"value":"مرن","title":"يتوسع مع المركز","description":"فعّل الوحدات والتكاملات وفق مرحلة نموك."}]},"style":{"variant":"dark","align":"center","paddingY":18,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-stat-strip"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"dark","align":"center","paddingY":38,"maxWidth":"full","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-stat-row"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"row-why-heading","type":"columns","props":{"anchor":"why","row":true,"layoutKey":"1","gap":18,"fullWidth":false,"minHeight":0,"verticalAlign":"stretch","items":[{"id":"col-why-heading","width":"1fr","modules":[{"id":"heading-why","type":"heading","props":{"anchor":"","eyebrow":"لماذا ماركتون؟","title":"ليست أداة عامة أُعيدت تسميتها لقطاع التدريب","body":"المنصة والخدمات وطريقة التشغيل مبنية من خبرة مباشرة في احتياجات مراكز ومعاهد التدريب في السوق السعودي.","level":"h2"},"style":{"variant":"light","align":"center","paddingY":15,"maxWidth":"reading","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-section-title"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"light","align":"center","paddingY":65,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-why-section"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"row-why-cards","type":"columns","props":{"anchor":"","row":true,"layoutKey":"1-1-1","gap":18,"fullWidth":false,"minHeight":0,"verticalAlign":"stretch","items":[{"id":"col-why-1","width":"1fr","modules":[{"id":"why-1","type":"feature","props":{"anchor":"","icon":"✦","title":"تخصص قطاعي","body":"مسارات العمل والتقارير والمصطلحات مصممة لواقع التدريب وليس لنشاط تجاري عام.","linkLabel":"","linkHref":""},"style":{"variant":"light","align":"right","paddingY":0,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"fade-up","animationDelay":90,"cssClass":"mt-why-card"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"col-why-2","width":"1fr","modules":[{"id":"why-2","type":"feature","props":{"anchor":"","icon":"◎","title":"خدمات وتقنية معًا","body":"يمكنك استخدام النظام وحده أو تشغيل التسويق والمبيعات والاستشارات داخل نفس المنظومة.","linkLabel":"","linkHref":""},"style":{"variant":"light","align":"right","paddingY":0,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"fade-up","animationDelay":180,"cssClass":"mt-why-card"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"col-why-3","width":"1fr","modules":[{"id":"why-3","type":"feature","props":{"anchor":"","icon":"↗","title":"تنفيذ قابل للقياس","body":"كل خطوة مرتبطة ببيانات ومؤشرات ومسؤوليات واضحة بدل الوعود والانطباعات.","linkLabel":"","linkHref":""},"style":{"variant":"light","align":"right","paddingY":0,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"fade-up","animationDelay":270,"cssClass":"mt-why-card"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"light","align":"right","paddingY":10,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-why-section"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]$blocks$::jsonb,
    true
  );
  v_document:=private_app.website_builder_validate_document(v_document);

  update website.pages set content=v_document,updated_at=now() where id=v_page_id;
  update website.content_documents
  set draft_document=v_document,published_document=v_document,
      draft_updated_at=now(),published_at=now(),updated_at=now()
  where site_id=v_site_id and entity_type='page' and entity_id=v_page_id;
end
$$;
commit;
